namespace Ehr.Data.Patients;

// Emergency access: a clinician opened the chart of a patient off their panel, and said why. The row grants that
// clinician the chart for a few hours without asking again; the reason is also in the audit log, as a break_glass
// event, which is what admins review. PHI, since the row names a patient and a reason: row-level security is enabled
// and forced on it and every write is recorded by trigger (db/policies). Rows are never changed or deleted.
public class BreakGlassAccess
{
    // UUIDv7, generated by whoever creates the row.
    public Guid Id { get; set; }

    public Guid PatientId { get; set; }

    // The staff account that opened the chart.
    public Guid ClinicianId { get; set; }

    public required string Reason { get; set; }

    public DateTimeOffset GrantedAt { get; set; }

    public DateTimeOffset ExpiresAt { get; set; }
}
